        return !owner || owner.expansion === 'expanded' && (owner.kind !== 'selection' || boxes.some(box => box.box.id === owner.sourceBoxId && !box.box.collapsed));
      }).map((thread) => {
        const isActive = display.nodes[thread.id]?.expansion === 'expanded';
